import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { organizationLogic, OrganizationUpdatePayload } from 'scenes/organizationLogic'
import { userLogic } from 'scenes/userLogic'

import { AvailableFeature, OrganizationType } from '~/types'

import { getIPRestrictionsError } from './ipRestrictionsUtils'

interface IPRestrictionsDraft {
    organizationId: string
    entries: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface organizationIPRestrictionsLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    currentOrganizationLoading: boolean // organizationLogic
    isAdminOrOwner: boolean | null // organizationLogic
    hasAvailableFeature: (feature: AvailableFeature, currentUsage?: number | undefined) => boolean // userLogic
    cleaned: string[]
    draft: IPRestrictionsDraft | null
    draftEntries: string[] | null
    editDisabledReason: string | null
    enabled: boolean
    entries: string[]
    isDirty: boolean
    saveDisabledReason: string | null
    toggleDisabledReason: string | null
    validationError: string | null
    values: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface organizationIPRestrictionsLogicActions {
    save: () => {
        value: true
    }
    setDraftEntries: (
        entries: string[] | null,
        organizationId: string | null
    ) => {
        entries: string[] | null
        organizationId: string | null
    }
    setEnabled: (enabled: boolean) => {
        enabled: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface organizationIPRestrictionsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        draftEntries: (
            draft: IPRestrictionsDraft | null,
            currentOrganization: OrganizationType | null
        ) => string[] | null
        entries: (currentOrganization: OrganizationType | null) => string[]
        enabled: (currentOrganization: OrganizationType | null) => boolean
        values: (draftEntries: string[] | null, entries: string[]) => string[]
        cleaned: (values: string[]) => string[]
        isDirty: (cleaned: string[], entries: string[]) => boolean
        validationError: (cleaned: string[]) => string | null
        editDisabledReason: (
            isAdminOrOwner: boolean | null,
            hasAvailableFeature: (feature: AvailableFeature, currentUsage?: number | undefined) => boolean // userLogic
        ) => string | null
        saveDisabledReason: (
            editDisabledReason: string | null,
            validationError: string | null,
            isDirty: boolean
        ) => string | null
        toggleDisabledReason: (
            enabled: boolean,
            isAdminOrOwner: boolean | null,
            editDisabledReason: string | null,
            isDirty: boolean
        ) => string | null
    }
}

export type organizationIPRestrictionsLogicType = MakeLogicType<
    organizationIPRestrictionsLogicValues,
    organizationIPRestrictionsLogicActions,
    Record<string, any>,
    organizationIPRestrictionsLogicMeta
>

export const organizationIPRestrictionsLogic = kea<organizationIPRestrictionsLogicType>([
    path(['scenes', 'settings', 'organization', 'organizationIPRestrictionsLogic']),
    connect({
        values: [
            organizationLogic,
            ['currentOrganization', 'currentOrganizationLoading', 'isAdminOrOwner'],
            userLogic,
            ['hasAvailableFeature'],
        ],
    }),
    actions({
        setDraftEntries: (entries: string[] | null, organizationId: string | null) => ({ entries, organizationId }),
        save: true,
        setEnabled: (enabled: boolean) => ({ enabled }),
    }),
    reducers({
        draft: [
            null as IPRestrictionsDraft | null,
            {
                setDraftEntries: (_, { entries, organizationId }) =>
                    entries !== null && organizationId !== null ? { entries, organizationId } : null,
            },
        ],
    }),
    selectors({
        draftEntries: [
            (s) => [s.draft, s.currentOrganization],
            (draft: IPRestrictionsDraft | null, organization: OrganizationType | null): string[] | null =>
                draft?.organizationId === organization?.id ? (draft?.entries ?? null) : null,
        ],
        entries: [
            (s) => [s.currentOrganization],
            (organization: OrganizationType | null): string[] => organization?.ip_restrictions ?? [],
        ],
        enabled: [
            (s) => [s.currentOrganization],
            (organization: OrganizationType | null): boolean => organization?.ip_restrictions_enabled ?? false,
        ],
        values: [
            (s) => [s.draftEntries, s.entries],
            (draft: string[] | null, entries: string[]): string[] => draft ?? entries,
        ],
        cleaned: [
            (s) => [s.values],
            (entries: string[]): string[] => [...new Set(entries.map((entry) => entry.trim()).filter(Boolean))],
        ],
        isDirty: [
            (s) => [s.cleaned, s.entries],
            (cleaned: string[], entries: string[]): boolean => JSON.stringify(cleaned) !== JSON.stringify(entries),
        ],
        validationError: [(s) => [s.cleaned], (entries: string[]): string | null => getIPRestrictionsError(entries)],
        editDisabledReason: [
            (s) => [s.isAdminOrOwner, s.hasAvailableFeature],
            (
                isAdminOrOwner: boolean | null,
                hasAvailableFeature: (feature: AvailableFeature, currentUsage?: number) => boolean
            ): string | null => {
                if (!isAdminOrOwner) {
                    return 'Only organization admins can change IP restrictions'
                }
                if (!hasAvailableFeature(AvailableFeature.IP_RESTRICTIONS)) {
                    return 'Upgrade your plan to configure IP restrictions'
                }
                return null
            },
        ],
        saveDisabledReason: [
            (s) => [s.editDisabledReason, s.validationError, s.isDirty],
            (editDisabledReason: string | null, validationError: string | null, isDirty: boolean): string | null =>
                editDisabledReason || validationError || (!isDirty ? 'No changes to save' : null),
        ],
        toggleDisabledReason: [
            (s) => [s.enabled, s.isAdminOrOwner, s.editDisabledReason, s.isDirty],
            (
                enabled: boolean,
                isAdminOrOwner: boolean | null,
                editDisabledReason: string | null,
                isDirty: boolean
            ): string | null => {
                if (enabled && isAdminOrOwner) {
                    return null
                }
                return editDisabledReason || (isDirty ? 'Save your IP restriction changes before enabling' : null)
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        [organizationLogic.actionTypes.loadCurrentOrganizationSuccess]: ({
            currentOrganization,
        }: {
            currentOrganization: OrganizationType | null
        }) => {
            if (values.draft && values.draft.organizationId !== currentOrganization?.id) {
                actions.setDraftEntries(null, null)
            }
        },
        [organizationLogic.actionTypes.updateOrganizationSuccess]: ({
            currentOrganization,
            payload,
        }: {
            currentOrganization: OrganizationType | null
            payload?: OrganizationUpdatePayload
        }) => {
            if (
                values.draft &&
                (values.draft.organizationId !== currentOrganization?.id || payload?.ip_restrictions !== undefined)
            ) {
                actions.setDraftEntries(null, null)
            }
        },
        save: () => {
            if (!values.currentOrganizationLoading && !values.saveDisabledReason) {
                organizationLogic.actions.updateOrganization({
                    ip_restrictions: values.cleaned,
                    ip_restrictions_enabled: values.enabled,
                })
            }
        },
        setEnabled: ({ enabled }) => {
            if (!values.currentOrganizationLoading && !values.toggleDisabledReason) {
                organizationLogic.actions.updateOrganization({ ip_restrictions_enabled: enabled })
            }
        },
    })),
])
